/**
 * Signing in to edit a planet. The planet's issuer is a pass issuer: a
 * planet takes only its passes, each made for that planet and its write
 * origin, and never the visitor's sign-in itself, which may be worth much
 * more at the issuer that gave it.
 *
 * Where the visitor signs in, and which pass issuers may be given that
 * sign-in to exchange, are the shell's own, declared by its deployment
 * (`ShellSignIn`, from webverse.config.json beside the shell's own files,
 * never beside the page, which may be a world author's folder), never by a
 * world or a planet or a pass issuer: a planet naming a pass issuer of its
 * own would otherwise be handed the visitor's sign-in. A planet whose pass
 * issuer the shell does not trust offers no editing in this shell.
 *
 * - `discoverIssuer` asks the shell's upstream issuer where it signs people
 *   in (OpenID Connect discovery, else its OAuth metadata), believing only a
 *   document naming that issuer, over https (or in clear on this machine).
 * - `startSignIn` keeps a fresh verifier and state in this tab's session
 *   storage and gives the authorize address: the shell's client, the
 *   verifier's S256 challenge, the state, and the shell's own return page.
 * - The return page hands the code and state to this tab; `finishSignIn`
 *   takes a return only from that page's origin and with the state this tab
 *   sent, redeems the code with the kept verifier, and keeps the upstream
 *   token in this tab's session storage only (`upstreamToken`).
 * - `exchangeForPass` exchanges it, at a trusted pass issuer's declared token
 *   endpoint, for a pass for one planet (OAuth token exchange, RFC 8693): its
 *   client id as the `audience` and its write origin as the `resource`. The
 *   pass is kept under the pass issuer, the planet's client and its write
 *   origin together (planetEdit.ts, `planetTokenKey`).
 *
 * Neither token is a world's: a world's scripts cannot read them.
 */
import { liveToken, planetTokenKey, trustedOrigin } from './planetEdit';

/** Where the sign-in in progress is kept, in this tab's session storage. */
export const PENDING_SIGN_IN = 'webverse:sign-in:pending';

const TOKEN_EXCHANGE = 'urn:ietf:params:oauth:grant-type:token-exchange';
const ACCESS_TOKEN_TYPE = 'urn:ietf:params:oauth:token-type:access_token';

/** Where an issuer signs a visitor in and redeems the code, as it says itself. */
export interface IssuerEndpoints {
  authorize: string;
  token: string;
}

/** The subset of Web Storage used here, so tests can pass a plain object. */
export interface KeyStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/** What the return page hands back. */
export interface SignInReturn {
  code: string | null;
  state: string | null;
  error: string | null;
}

export type SignInOutcome = { ok: true } | { ok: false; reason: string };

type Fetch = (url: string, init?: RequestInit) => Promise<Response>;

const base64url = (bytes: Uint8Array) => {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};
const random = (bytes: number) => base64url(crypto.getRandomValues(new Uint8Array(bytes)));

/** An issuer's metadata, from OpenID Connect discovery or, failing that, OAuth authorization server metadata; only one naming the issuer. */
async function metadataOf(issuer: string, fetchImpl: Fetch): Promise<Record<string, unknown> | null> {
  if (!trustedOrigin(issuer)) return null;
  const trimmed = issuer.replace(/\/+$/, '');
  const u = new URL(trimmed);
  const path = u.pathname === '/' ? '' : u.pathname;
  for (const at of [`${trimmed}/.well-known/openid-configuration`, `${u.origin}/.well-known/oauth-authorization-server${path}`]) {
    let doc: Record<string, unknown>;
    try {
      const res = await fetchImpl(at);
      if (!res.ok) continue;
      doc = (await res.json()) as Record<string, unknown>;
    } catch {
      continue;
    }
    return doc.issuer === issuer ? doc : null;
  }
  return null;
}

const trusted = (v: unknown): v is string => typeof v === 'string' && trustedOrigin(v) !== undefined;

/** Where the issuer says it signs visitors in; null when it says nothing believable. */
export async function discoverIssuer(issuer: string, fetchImpl: Fetch): Promise<IssuerEndpoints | null> {
  const doc = await metadataOf(issuer, fetchImpl);
  if (!doc || !trusted(doc.authorization_endpoint) || !trusted(doc.token_endpoint)) return null;
  return { authorize: doc.authorization_endpoint, token: doc.token_endpoint };
}

/** A pass issuer the shell trusts with its visitors' sign-in, by its exact token endpoint. */
export interface TrustedPassIssuer {
  issuer: string;
  tokenEndpoint: string;
}

/** The shell's own sign-in, as its deployment declares it: where visitors sign in, as which client, and which pass issuers may exchange that. */
export interface ShellSignIn {
  issuer: string;
  clientId: string;
  passIssuers: TrustedPassIssuer[];
}

/** The deployment's `{ "signIn": { issuer, clientId, passIssuers: [{ issuer, tokenEndpoint }] } }`; null without a usable one. Addresses must be https, or in clear on this machine; a pass issuer that is not is left out. */
export function readShellSignIn(json: unknown): ShellSignIn | null {
  const c = ((json && typeof json === 'object' ? (json as { signIn?: unknown }).signIn : undefined) ?? null) as Record<string, unknown> | null;
  if (!c || typeof c !== 'object' || !trusted(c.issuer) || typeof c.clientId !== 'string' || c.clientId === '') return null;
  const passIssuers = (Array.isArray(c.passIssuers) ? c.passIssuers : [])
    .map((p) => (p ?? {}) as Record<string, unknown>)
    .filter((p): p is { issuer: string; tokenEndpoint: string } => trusted(p.issuer) && trusted(p.tokenEndpoint))
    .map((p) => ({ issuer: p.issuer, tokenEndpoint: p.tokenEndpoint }));
  return { issuer: c.issuer, clientId: c.clientId, passIssuers };
}

/**
 * Where the shell's own files are, from the address of the shell's own code: in a build its chunks sit one
 * folder below them (`assets/`, `boot-assets/`), in development its source is served from the server's root.
 * Never the page's base: a page that boots the shell may be a world's, in a folder of the world author's files.
 */
export function shellBaseFrom(moduleUrl: string, dev: boolean): string {
  return new URL(dev ? '/' : '../', moduleUrl).href;
}

/** The shell's sign-in, from the deployment's webverse.config.json beside the shell's own files (`shellBaseFrom`). */
export async function loadShellSignIn(shellBase: string, fetchImpl: Fetch): Promise<ShellSignIn | null> {
  try {
    const res = await fetchImpl(new URL('webverse.config.json', shellBase).href);
    return res.ok ? readShellSignIn(await res.json()) : null;
  } catch {
    return null;
  }
}

/** The trusted pass issuer a planet names, or null when the shell does not trust it with its visitors' sign-in. */
export function passIssuerFor(config: ShellSignIn | null, issuer: string | undefined): TrustedPassIssuer | null {
  return (issuer && config?.passIssuers.find((p) => p.issuer === issuer)) || null;
}

/** Where this tab notes the pass issuers the visitor has chosen to use: only those get a pass without a click. */
const USED_PASS_ISSUERS = 'webverse:pass-issuers-used';

export function passIssuerUsed(session: Pick<KeyStore, 'getItem'>, issuer: string): boolean {
  try {
    const used = JSON.parse(session.getItem(USED_PASS_ISSUERS) ?? '[]') as unknown;
    return Array.isArray(used) && used.includes(issuer);
  } catch {
    return false;
  }
}

export function usePassIssuer(session: KeyStore, issuer: string): void {
  if (passIssuerUsed(session, issuer)) return;
  let used: unknown = [];
  try {
    used = JSON.parse(session.getItem(USED_PASS_ISSUERS) ?? '[]');
  } catch {
    used = [];
  }
  session.setItem(USED_PASS_ISSUERS, JSON.stringify([...(Array.isArray(used) ? used : []), issuer]));
}

/** Where this tab keeps its upstream sign-in: under the issuer and the shell's client there. */
export const upstreamTokenKey = (issuer: string, clientId: string) => `webverse:upstream-session:${JSON.stringify([issuer, clientId])}`;

/** This tab's upstream sign-in, while it has not expired; null otherwise. */
export function upstreamToken(session: Pick<KeyStore, 'getItem'>, issuer: string, clientId: string): string | null {
  try {
    return liveToken(session.getItem(upstreamTokenKey(issuer, clientId)));
  } catch {
    return null;
  }
}

/** Keep a fresh verifier and state for this tab, and give the upstream issuer's authorize address. */
export async function startSignIn(o: { issuer: string; clientId: string; redirectUri: string; endpoints: IssuerEndpoints; pending: KeyStore }): Promise<string> {
  const verifier = random(32);
  const state = random(24);
  const challenge = base64url(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier))));
  o.pending.setItem(PENDING_SIGN_IN, JSON.stringify({ verifier, state, issuer: o.issuer, clientId: o.clientId, redirectUri: o.redirectUri, token: o.endpoints.token }));
  const target = new URL(o.endpoints.authorize);
  target.searchParams.set('response_type', 'code');
  target.searchParams.set('client_id', o.clientId);
  target.searchParams.set('redirect_uri', o.redirectUri);
  target.searchParams.set('state', state);
  target.searchParams.set('code_challenge', challenge);
  target.searchParams.set('code_challenge_method', 'S256');
  target.searchParams.set('scope', 'openid');
  return target.href;
}

/** Redeem the code the return page handed back, from `origin`, and keep the upstream token in this tab's session. */
export async function finishSignIn(o: { origin: string; message: SignInReturn; pending: KeyStore; fetchImpl: Fetch }): Promise<SignInOutcome> {
  let held: Record<string, unknown> = {};
  try {
    held = JSON.parse(o.pending.getItem(PENDING_SIGN_IN) ?? '{}') as Record<string, unknown>;
  } catch {
    held = {};
  }
  const { verifier, state, issuer, clientId, redirectUri, token } = held;
  if (typeof state !== 'string' || o.message.state !== state) return { ok: false, reason: 'state' };
  if (typeof redirectUri !== 'string' || o.origin !== new URL(redirectUri).origin) return { ok: false, reason: 'origin' };
  o.pending.removeItem(PENDING_SIGN_IN);
  if (o.message.error) return { ok: false, reason: o.message.error };
  if (typeof verifier !== 'string' || typeof issuer !== 'string' || typeof clientId !== 'string' || typeof token !== 'string' || !o.message.code) {
    return { ok: false, reason: 'refused' };
  }
  const form = new URLSearchParams({ grant_type: 'authorization_code', code: o.message.code, redirect_uri: redirectUri, code_verifier: verifier, client_id: clientId });
  let res: Response;
  try {
    res = await o.fetchImpl(token, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: form.toString() });
  } catch {
    return { ok: false, reason: 'unavailable' };
  }
  const got = (res.ok ? await res.json().catch(() => ({})) : {}) as { access_token?: unknown };
  if (typeof got.access_token !== 'string' || !got.access_token) return { ok: false, reason: 'refused' };
  o.pending.setItem(upstreamTokenKey(issuer, clientId), got.access_token);
  return { ok: true };
}

/** Exchange the upstream sign-in, at a trusted pass issuer's declared endpoint, for a pass for one planet and its write origin; keep the pass for that planet. */
export async function exchangeForPass(o: {
  passIssuer: string;
  exchange: string;
  subjectToken: string;
  audience: string;
  resource: string;
  keep: KeyStore;
  fetchImpl: Fetch;
}): Promise<SignInOutcome> {
  const form = new URLSearchParams({
    grant_type: TOKEN_EXCHANGE,
    subject_token: o.subjectToken,
    subject_token_type: ACCESS_TOKEN_TYPE,
    audience: o.audience,
    resource: o.resource,
  });
  let res: Response;
  try {
    res = await o.fetchImpl(o.exchange, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: form.toString() });
  } catch {
    return { ok: false, reason: 'unavailable' };
  }
  const got = (await res.json().catch(() => ({}))) as { access_token?: unknown; error?: unknown };
  if (!res.ok || typeof got.access_token !== 'string' || !got.access_token) return { ok: false, reason: typeof got.error === 'string' ? got.error : 'refused' };
  o.keep.setItem(planetTokenKey(o.passIssuer, o.audience, o.resource), got.access_token);
  return { ok: true };
}
